# Hypothesis: TypeIs narrows both branches of an int | str check, TypeGuard narrows only the positive branch, and an Any-typed input is narrowed by TypeIs to str.
from typing import Any, TypeGuard, TypeIs, reveal_type


def is_str_is(v: object) -> TypeIs[str]:
    return isinstance(v, str)


def is_str_guard(v: object) -> TypeGuard[str]:
    return isinstance(v, str)


def check(v: int | str) -> str:
    if is_str_is(v):
        reveal_type(v)
        out = v
    else:
        reveal_type(v)
        out = str(v)
    return out


def check_guard(v: int | str) -> str:
    if is_str_guard(v):
        reveal_type(v)
        return v
    reveal_type(v)
    return str(v)


def from_any(v: Any) -> str:
    if is_str_is(v):
        reveal_type(v)
        return v
    return repr(v)


print(check(3), check('x'))
print(check_guard(3), check_guard('x'))
print(from_any(5), from_any('y'))
